import React, { useEffect, useState, useMemo } from "react";
import {
  MapContainer,
  TileLayer,
  CircleMarker,
  Popup,
  Circle,
  useMap,
} from "react-leaflet";
import "leaflet/dist/leaflet.css";

// Componente para ajustar la vista del mapa dinámicamente
const ChangeView = ({ coordenadas }) => {
  const map = useMap();

  useEffect(() => {
    if (coordenadas) {
      map.setView([coordenadas.lat, coordenadas.lng], 7); // Centra el mapa
    }
  }, [coordenadas, map]);

  return null;
};

const MapaMexico = ({ coordenadas, theme }) => {
  const [circleScale, setCircleScale] = useState(1);
  const [opacity, setOpacity] = useState(0.6);

  // Utiliza useMemo para evitar recrear la URL cada vez que se renderice
  const tileLayerUrl = useMemo(() => {
    return theme === "dark"
      ? "https://tiles.stadiamaps.com/tiles/alidade_smooth_dark/{z}/{x}/{y}{r}.png"
      : "https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png";
  }, [theme]);

  // Manejo del efecto de expansión del círculo
  useEffect(() => {
    if (!coordenadas) return;

    setCircleScale(1); 
    setOpacity(0.6);

    const interval = setInterval(() => {
      setCircleScale((prev) => prev + 0.05);
      setOpacity((prev) => Math.max(prev - 0.01, 0));

      if (circleScale > 3 || opacity <= 0) {
        setCircleScale(1);
        setOpacity(0.6);
      }
    }, 50);

    return () => clearInterval(interval); 
  }, [coordenadas, circleScale, opacity]);

  return (
    <MapContainer
      center={[23.6345, -102.5528]} // Centro de México
      zoom={5}
      style={{ height: "100vh", width: "100%" }}
      key={`map-container-${theme}`} // Crea un nuevo MapContainer cuando cambia el tema
    >
      <TileLayer url={tileLayerUrl} />
      <ChangeView coordenadas={coordenadas} />

      {/* Marcadores y ondas sísmicas */}
      {coordenadas && (
        <>
          <CircleMarker
            center={[coordenadas.lat, coordenadas.lng]}
            radius={10}
            color="red"
            fillColor="red"
            fillOpacity={0.7}
          >
            <Popup>
              <b>Ubicación del Sismo</b> <br />
              Lat: {coordenadas.lat}, Lng: {coordenadas.lng}
            </Popup>
          </CircleMarker>

          {/* Círculo expandible */}
          <Circle
            center={[coordenadas.lat, coordenadas.lng]}
            radius={circleScale * 50000}
            color="red"
            fillColor="red"
            fillOpacity={opacity}
            stroke={false}
          />
        </>
      )}
    </MapContainer>
  );
};

export default MapaMexico;
